from itertools import combinations
import random

def check_girth(edges, n, min_girth):
    """Check if graph has girth at least min_girth"""
    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # BFS from each vertex to find shortest cycle
    for start in range(n):
        # BFS to find shortest cycle through start
        visited = {start: 0}
        queue = [(start, -1, 0)]  # (current, parent, depth)
        while queue:
            node, parent, depth = queue.pop(0)
            if depth >= min_girth:
                continue
            for neighbor in adj[node]:
                if neighbor == parent:
                    continue
                if neighbor in visited:
                    cycle_len = depth + 1 - visited[neighbor]
                    if cycle_len < min_girth:
                        return False
                else:
                    visited[neighbor] = depth + 1
                    queue.append((neighbor, node, depth + 1))
    return True

def is_3_colorable(edges, n):
    """Check if graph is 3-colorable using backtracking"""
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    colors = [-1] * n

    def backtrack(v):
        if v == n:
            return True
        for c in range(3):
            valid = True
            for neighbor in adj[v]:
                if colors[neighbor] == c:
                    valid = False
                    break
            if valid:
                colors[v] = c
                if backtrack(v + 1):
                    return True
                colors[v] = -1
        return False

    return backtrack(0)

