def has_4_cycle(edges, n):
    """Check for 4-cycles in bipartite graph"""
    adj_a = [[] for _ in range(12)]
    for u, v in edges:
        adj_a[u].append(v - 12)

    # Check if any two vertices in A share 2+ neighbors in B
    for i in range(12):
        for j in range(i+1, 12):
            common = set(adj_a[i]) & set(adj_a[j])
            if len(common) >= 2:
                return True
    return False

def has_6_cycle(edges, n):
    """Check for 6-cycles in bipartite graph"""
    adj_a = [[] for _ in range(12)]
    adj_b = [[] for _ in range(12)]
    for u, v in edges:
        adj_a[u].append(v - 12)
        adj_b[v - 12].append(u)

    # A 6-cycle in bipartite graph: a1-b1-a2-b2-a3-b3-a1
    # Check all paths of length 3 from each vertex in A
    for start in range(12):
        # BFS up to depth 3
        visited = {start: 0}
        queue = [(start, 0)]  # (vertex in A, depth)
        while queue:
            node, depth = queue.pop(0)
            if depth >= 3:
                continue
            # Go to B
            for b in adj_a[node]:
                # Go back to A
                for a2 in adj_b[b]:
                    if a2 == start and depth == 2:
                        return True  # Found 6-cycle
                    if a2 not in visited or visited[a2] > depth + 1:
                        visited[a2] = depth + 1
                        if depth + 1 < 3:
                            queue.append((a2, depth + 1))
    return False

